'use strict';
const Capabilities=Object.freeze({"LightingStatic":"lighting.static","LightingOff":"lighting.off","LightingEffect":"lighting.effect","FanProfile":"fan.profile","PowerWindowsScheme":"power.windowsScheme","ProcessPolicy":"process.policy","SystemInfo":"system.info","Release":"device.release","SensorTemperature":"sensor.temperature","SensorFanRpm":"sensor.fanRpm"});
const Effects=Object.freeze({Static:'static',Off:'off',Breathing:'breathing',Rainbow:'rainbow'});
const Themes=Object.freeze({Auto:'auto',Light:'light',Dark:'dark'});
const TriggerKinds=Object.freeze({Daily:'daily',Process:'process'});
const AutomationLimits=Object.freeze({Rules:64,Commands:16,Name:128});
const AutomationMethods=Object.freeze({Read:'app.automation.read',Write:'app.automation.write'});
const Priorities=Object.freeze(['Idle','BelowNormal','Normal','AboveNormal','High']);
const LightingLimits=Object.freeze({MinPeriod:2,MaxPeriod:60,DefaultPeriod:6});
const ApplyStatus=Object.freeze({Applied:'applied',Unchanged:'unchanged',Accepted:'accepted',Restored:'restored',Released:'released',Verified:'verified'});
const clone = value => structuredClone(value);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state = {page:'overview',language:'zh-CN',connected:false,loading:true,busy:false,error:'',snapshot:{devices:[],telemetry:[],diagnostics:[]},prefs:{schemaVersion:1},lighting:{devices:{},sync:false,members:[],independent:{},group:{effect:'static',color:'#76AFFF',brightness:.35}},savedLighting:null,selected:'',fanSelected:'',fanTarget:'radiator',fanDraft:null,fanDirty:false,lightingDirty:false,errors:[],history:new Map(),plugins:[],pluginsLoaded:false,theme:Themes.Auto,automation:{schemaVersion:1,rules:[],status:[]},automationLoaded:false,automationError:'',automationLoading:false};
const main=document.getElementById('main'), modal=document.getElementById('modal');
const t=(zh,en)=>state.language==='en'?en:zh;
let nextId=0, toastTimer, polling=false, preferencesLoaded=false;
const pending=new Map();
window.chrome?.webview?.addEventListener('message', event=>{const message=event.data;const request=pending.get(message.id);if(!request)return;clearTimeout(request.timer);pending.delete(message.id);message.error?request.reject(new Error(message.error)):request.resolve(message.result)});
function rpc(method,params={}){return new Promise((resolve,reject)=>{if(!window.chrome?.webview){reject(new Error(t('本页必须在光序桌面应用中打开。','Open this page in the LightOrder desktop app.')));return}if(pending.size>=12){reject(new Error(t('操作繁忙，请稍后。','Too many pending requests.')));return}const id=++nextId;const timer=setTimeout(()=>{pending.delete(id);reject(new Error(t('请求超时；写入结果未知，请刷新状态。','Request timed out; write outcome unknown. Refresh status.')))},25000);pending.set(id,{resolve,reject,timer});window.chrome.webview.postMessage({id,method,params})})}
function toast(text){const el=document.getElementById('toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function showModal(body){document.getElementById('modal-content').innerHTML=body;if(!modal.open)modal.showModal();modal.querySelectorAll('[data-close]').forEach(button=>button.onclick=()=>modal.close());modal.querySelector('button')?.focus()}
const has=(device,capability)=>device.capabilities?.includes(capability);
const devices=()=>state.snapshot.devices||[];
const lights=()=>devices().filter(d=>has(d,Capabilities.LightingStatic)||has(d,Capabilities.LightingOff));
const fans=()=>devices().filter(d=>has(d,Capabilities.FanProfile));
const deviceById=id=>devices().find(d=>d.id===id);
const StatusLabels=Object.freeze({disabled:['未启用','Disabled'],running:['执行中','Running'],completed:['已完成','Completed'],paused:['已暂停','Paused'],ready:['已连接','Connected'],available:['已连接','Connected'],connected:['已连接','Connected'],online:['已连接','Connected'],monitoring:['监测中','Monitoring'],active:['控制中','Active'],'read-only':['只读','Read-only'],readonly:['只读','Read-only'],partial:['部分可用','Partial'],unavailable:['不可用','Unavailable'],offline:['离线','Offline'],disconnected:['已断开','Disconnected'],unsupported:['暂不支持','Unsupported'],ambiguous:['需确认设备','Check device'],'recovery-required':['待恢复','Restore needed'],restored:['已恢复','Restored'],released:['已恢复','Restored'],idle:['待机','Idle'],inactive:['未启用','Inactive'],failed:['操作失败','Failed'],expired:['已到期','Expired'],starting:['连接中','Connecting']});
function statusLabel(value){if(!value)return '';const label=StatusLabels[String(value).toLowerCase()];return label?t(...label):t('待确认','Unconfirmed')}
function deviceLabel(device){if(has(device,Capabilities.FanProfile))return t('散热控制器','Cooling controller');if(has(device,Capabilities.SensorTemperature)||has(device,Capabilities.SensorFanRpm))return t('硬件监测','Hardware monitor');if(has(device,Capabilities.SystemInfo))return t('系统信息','System information');if(has(device,Capabilities.PowerWindowsScheme)||has(device,Capabilities.ProcessPolicy))return t('Windows 系统策略','Windows policies');return device.name}
function deviceSummary(device){if(has(device,Capabilities.FanProfile))return t('冷排与机箱 · 独立温控','Radiator & case · independent curves');if(has(device,Capabilities.SensorTemperature)||has(device,Capabilities.SensorFanRpm))return t('温度与转速 · 只读监测','Temperature & fan speed · read-only');if(has(device,Capabilities.SystemInfo))return t('硬件配置与系统信息','Hardware and system information');if(has(device,Capabilities.PowerWindowsScheme)||has(device,Capabilities.ProcessPolicy))return t('电源计划与进程策略','Power schemes and process policies');if(has(device,Capabilities.LightingStatic))return t('颜色、亮度与常亮','Color, brightness and static lighting');return t('设备状态','Device status')}
const TelemetryLabels=Object.freeze({'cpu.temperature':['处理器温度','CPU temperature'],'radiator.rpm':['冷排风扇','Radiator fan'],'case.rpm':['机箱风扇','Case fan'],'pump.rpm':['水泵','Pump']});
function telemetryLabel(sample){const label=TelemetryLabels[sample.name];return label?t(...label):sample.name}
function primarySamples(samples,limit=4){const canonical=Object.keys(TelemetryLabels);return samples.filter(s=>canonical.includes(s.name)).sort((a,b)=>canonical.indexOf(a.name)-canonical.indexOf(b.name)).slice(0,limit)}
const validColor=color=>typeof color==='string'&&/^#[a-f0-9]{6}$/i.test(color);
const isDynamic=effect=>[Effects.Breathing,Effects.Rainbow].includes(effect);
function validLight(value){return !!value&&Object.values(Effects).includes(value.effect)&&validColor(value.color)&&finite(value.brightness)&&value.brightness>=0&&value.brightness<=1&&(value.periodSeconds===undefined?!isDynamic(value.effect):finite(value.periodSeconds)&&value.periodSeconds>=LightingLimits.MinPeriod&&value.periodSeconds<=LightingLimits.MaxPeriod)}
function normalizeLight(value){return validLight(value)?{effect:value.effect,color:value.color,brightness:value.brightness,periodSeconds:value.periodSeconds??LightingLimits.DefaultPeriod}:null}
function lightCapability(setting){return setting.effect===Effects.Off?Capabilities.LightingOff:isDynamic(setting.effect)?Capabilities.LightingEffect:Capabilities.LightingStatic}
function supportsEffect(device,effect){if(!device||!has(device,lightCapability({effect})))return false;if(!isDynamic(effect))return true;const effects=device.metadata?.effects;return Array.isArray(effects)&&effects.some(value=>(typeof value==='string'?value:value?.id??value?.name??value?.effect)===effect)}
function lightCommand(deviceId,setting,phaseUtc){if(!validLight(setting))throw new Error(t('灯光配置无效','Invalid lighting setting'));const parameters={color:setting.color,brightness:setting.brightness,operationId:crypto.randomUUID()};if(isDynamic(setting.effect)){parameters.effect=setting.effect;parameters.periodSeconds=setting.periodSeconds;if(phaseUtc)parameters.phaseUtc=phaseUtc}return {deviceId,capability:lightCapability(setting),parameters}}
function applyTheme(){const dark=state.theme===Themes.Dark||(state.theme===Themes.Auto&&window.matchMedia?.('(prefers-color-scheme: dark)').matches);document.documentElement.dataset.theme=dark?Themes.Dark:Themes.Light;document.documentElement.style.colorScheme=dark?'dark':'light'}
function effective(id,config=state.lighting){return config.sync&&config.members.includes(id)?config.group:config.devices[id]}
function current(){return effective(state.selected)}
function markLighting(){state.lightingDirty=true;updateSave();updatePreview()}
function updateSave(){const button=document.getElementById('apply');if(button){const dirty=state.page==='lighting'?state.lightingDirty:state.fanDirty;button.disabled=!dirty||!state.connected||state.busy;button.className=dirty?'primary':'saved-button';button.innerHTML=icon(dirty?'save':'check')+t(dirty?'保存并应用':'已保存',dirty?'Save & apply':'Saved')}const discard=document.getElementById('discard');if(discard)discard.hidden=!(state.page==='lighting'?state.lightingDirty:state.fanDirty)}
function saveControls(){const dirty=state.page==='lighting'?state.lightingDirty:state.fanDirty;return `<div class="top-save"><button id="discard" class="ghost small" ${dirty?'':'hidden'} aria-label="${t('撤销修改','Discard changes')}">${icon('undo')}</button><div class="save-split"><button id="apply" class="${dirty?'primary':'saved-button'}" ${!dirty||!state.connected||state.busy?'disabled':''}>${icon(dirty?'save':'check')}${t(dirty?'保存并应用':'已保存',dirty?'Save & apply':'Saved')}</button>${state.page==='lighting'?`<details class="save-menu"><summary aria-label="${t('更多保存选项','More save options')}" title="${t('更多保存选项','More save options')}"><svg class="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></summary><div class="save-popover"><button id="save-scene">${t('另存为场景…','Save as scene…')}</button><button id="open-scenes">${t('我的场景…','My scenes…')}</button></div></details>`:''}</div></div>`}
function head(title,subtitle,editing=false){return `<header class="page-head"><div><h1>${title}</h1><p>${subtitle}</p></div>${editing?saveControls():`<span class="status-pill">${icon(state.connected?'check':'info')}${state.connected?t('服务已连接','Service connected'):t('服务未连接','Service unavailable')}</span>`}</header>`}
function empty(text){return `<div class="empty-state">${icon('info')}<p>${text}</p></div>`}
function setupCard(){return `<section class="section setup-card"><img src="app-icon.svg" alt=""><h2>${t('先连接本地硬件服务','Connect your hardware service')}</h2><p>${state.loading?t('正在连接服务…','Connecting…'):t('首次使用需要安装光序后台服务。完成配置后，日常调节灯光和散热无需逐项申请管理员权限。','Install the LightOrder background service once. Daily lighting and cooling controls then run without individual administrator prompts.')}</p>${state.error?`<div class="readonly">${esc(state.error)}</div>`:''}<div class="setup-actions"><button id="setup-service" class="primary">${icon('shield')}${t('打开安装程序','Open setup')}</button><button id="retry">${t('重新连接','Retry connection')}</button></div><p>${t('安装、修复和卸载时，Windows 可能要求授权。界面关闭不会停止后台控制。','Windows may request permission during setup, repair or removal. Closing this window keeps background control running.')}</p></section>`}
function deviceRows(list){return list.length?list.map(d=>`<div class="device-line"><div class="device-symbol">${icon(has(d,Capabilities.FanProfile)?'fan':has(d,Capabilities.LightingStatic)?'light':'chip')}</div><div><h3>${esc(deviceLabel(d))}</h3><small>${esc(deviceSummary(d))}</small></div><span class="trailing">${esc(statusLabel(d.status))}</span></div>`).join(''):empty(t('未发现可用设备。请检查插件与连接。','No devices discovered. Check plugins and connections.'))}
function overview(){return head(t('总览','Overview'),t('设备状态与常用设置','Device status and everyday controls'))+(state.connected?`<section class="section overview-readings"><div class="section-head"><h2>${t('运行状态','Live status')}</h2><span class="badge">${t('实时采样','Live readings')}</span></div>${telemetryReadouts(4)}</section><div class="quick-controls"><button data-go-page="lighting">${icon('light')}<span><strong>${t('灯光','Lighting')}</strong><small>${lights().length} ${t('个设备','devices')} · ${state.lighting.sync?t('同步已启用','Sync on'):t('独立控制','Independent')}</small></span>${icon('arrow')}</button><button data-go-page="cooling">${icon('fan')}<span><strong>${t('散热','Cooling')}</strong><small>${fans().length} ${t('个控制器','controllers')}</small></span>${icon('arrow')}</button><button data-go-page="automation">${icon('clock')}<span><strong>${t('自动化','Automation')}</strong><small>${t('定时与进程规则','Schedule & process rules')}</small></span>${icon('arrow')}</button></div><div class="grid2"><section class="section"><div class="section-head"><h2>${t('温度变化','Temperature history')}</h2><span class="badge">${t('本次会话 · 最多10分钟','This session · up to 10 min')}</span></div>${historyPanels('temperature',1,true)}</section><section class="section"><div class="section-head"><h2>${t('我的设备','My devices')}</h2><button id="refresh" class="small ghost">${t('刷新发现','Rediscover')}</button></div>${deviceRows(devices())}</section></div><p class="graph-hint">${t('未读取或无效值显示为 —。关闭窗口后，后台服务仍继续工作。','Unavailable or invalid readings show —. The service keeps running when the window closes.')}</p>`:setupCard())}
function telemetryReadouts(limit=4){const samples=primarySamples(state.snapshot.telemetry||[],limit);return samples.length?`<div class="telemetry-grid">${samples.map(s=>`<div class="metric"><small>${esc(telemetryLabel(s))}</small><strong>${finite(s.value)?esc(Number(s.value.toFixed(1))):'—'} <small>${esc(s.unit)}</small></strong><div class="telemetry-time">${esc(formatTime(s.timestamp))}</div></div>`).join('')}</div>`:empty(t('等待遥测数据','Waiting for telemetry'))}
function lighting(){if(!state.connected)return head(t('灯光','Lighting'),t('设备灯效与同步设置','Lighting and synchronization'))+setupCard();const list=lights();if(!list.length)return head(t('灯光','Lighting'),t('设备灯效与同步设置','Lighting and synchronization'))+empty(t('未发现灯光能力。请检查服务插件。','No lighting capability discovered. Check service plugins.'));if(!list.some(d=>d.id===state.selected))state.selected=list[0].id;const d=deviceById(state.selected),c=current(),group=state.lighting.sync&&state.lighting.members.includes(d.id);return head(t('灯光','Lighting'),t('设备灯效与同步设置','Lighting and synchronization'),true)+`<section class="sync-banner ${state.lighting.sync?'enabled':''}"><div class="sync-symbol">${icon('link')}</div><div class="sync-copy"><h3>${t('神光同步','Lighting sync')}</h3><p>${t(state.lighting.sync?'所选设备共享颜色与灯效。退出时恢复各自配置。':'默认独立设置；由你选择需要同步的设备。',state.lighting.sync?'Selected devices share a lighting setting; leaving restores their saved settings.':'Independent by default. Choose which devices to synchronize.')}</p></div>${state.lighting.sync?`<button id="members" class="small">${t('管理成员','Members')}</button>`:''}<button class="switch ${state.lighting.sync?'on':''}" id="sync-toggle" role="switch" aria-checked="${state.lighting.sync}" aria-label="${t('神光同步','Lighting sync')}"></button></section><div class="light-workspace"><div><div class="stage-panel"><div class="stage-label"><strong>${t('灯光预览','Lighting preview')}</strong><span>${t('配置示意','Configuration')}</span></div><div class="generic-preview" id="preview" style="--glow:${c?.effect==='static'?c.color:'#c9d0da'}"><div class="light-ring">${icon('light')}</div></div><p class="stage-foot">${t('配置预览不代表硬件读回','Preview is not hardware readback')}</p></div><div class="device-picks">${list.map((item,i)=>`<button class="device-pick ${item.id===d.id?'active':''}" data-device-index="${i}">${icon('light')}<span class="name">${esc(deviceLabel(item))}<small>${esc(statusLabel(item.status))} · ${state.lighting.sync&&state.lighting.members.includes(item.id)?t('同步成员','Sync member'):t('独立设置','Independent')}</small></span><span class="color-dot" style="background:${effective(item.id)?.color||'#c9d0da'}"></span>${icon('arrow')}</button>`).join('')}</div></div>${lightEditor(d,c,group)}</div>`}
function syncDialog(){const list=lights();showModal(`<div class="modal-body"><h2>${t('选择同步设备','Select sync devices')}</h2><p>${t('加入前保存独立配置。尚无已知配置的设备需要先独立保存一次。','Independent settings are preserved before joining. First save a setting for devices whose configuration is unknown.')}</p>${list.map((d,i)=>`<label class="check-row"><input type="checkbox" data-member="${i}" ${state.lighting.members.includes(d.id)?'checked':''} ${!validLight(state.lighting.devices[d.id])||!has(d,Capabilities.LightingStatic)?'disabled':''}><span>${esc(deviceLabel(d))}<small>${validLight(state.lighting.devices[d.id])?t('支持恢复已知配置','Known setting can be restored'):t('尚无已知配置','No known setting')}</small></span></label>`).join('')}</div><div class="modal-footer"><button data-close>${t('取消','Cancel')}</button><button class="primary" id="confirm-sync">${t('保存成员','Use selection')}</button></div>`);document.getElementById('confirm-sync').onclick=()=>{const members=[...modal.querySelectorAll('[data-member]:checked:not(:disabled)')].map(el=>list[Number(el.dataset.member)].id);if(members.length<2){toast(t('请至少选择两个设备','Select at least two devices'));return}for(const id of state.lighting.members){if(!members.includes(id)&&state.lighting.independent[id]){state.lighting.devices[id]=clone(state.lighting.independent[id]);delete state.lighting.independent[id]}}for(const id of members)if(!state.lighting.independent[id])state.lighting.independent[id]=clone(state.lighting.devices[id]);if(!state.lighting.sync)state.lighting.group=clone(state.lighting.devices[members[0]]);state.lighting.members=members;state.lighting.sync=true;state.selected=members[0];state.lightingDirty=true;modal.close();render()}}
function disableSync(){showModal(`<div class="modal-body"><h2>${t('恢复独立灯光？','Restore independent lighting?')}</h2><p>${t('各设备将恢复加入同步前的已知配置。点击顶部保存后应用。','Each device will return to its known pre-sync configuration when you save and apply.')}</p></div><div class="modal-footer"><button data-close>${t('取消','Cancel')}</button><button id="confirm-off" class="primary">${t('恢复独立配置','Restore individual settings')}</button></div>`);document.getElementById('confirm-off').onclick=()=>{for(const id of state.lighting.members)if(state.lighting.independent[id])state.lighting.devices[id]=clone(state.lighting.independent[id]);state.lighting.sync=false;state.lighting.members=[];state.lighting.independent={};state.lightingDirty=true;modal.close();render()}}
const FanPresets=Object.freeze({silent:{mode:'curve',radiatorPercent:40,casePercent:25,radiatorCurve:[{temperature:40,duty:40},{temperature:55,duty:40},{temperature:65,duty:60},{temperature:80,duty:100}],caseCurve:[{temperature:40,duty:25},{temperature:55,duty:30},{temperature:65,duty:55},{temperature:80,duty:100}]},balanced:{mode:'curve',radiatorPercent:65,casePercent:55,radiatorCurve:[{temperature:40,duty:65},{temperature:55,duty:65},{temperature:65,duty:80},{temperature:80,duty:100}],caseCurve:[{temperature:40,duty:55},{temperature:55,duty:65},{temperature:65,duty:80},{temperature:80,duty:100}]}});
function fanPresetKey(){return Object.keys(FanPresets).find(key=>{const preset=FanPresets[key],p=state.fanDraft;return p&&p.mode===preset.mode&&['radiatorCurve','caseCurve'].every(curve=>JSON.stringify(p[curve])===JSON.stringify(preset[curve]))})||'custom'}
function fanPresets(){const active=fanPresetKey();return `<div class="mode-cards">${[['silent','moon',t('静音','Silent'),t('较低转速','Lower fan speed')],['balanced','sun',t('平衡','Balanced'),t('自动调节','Automatic cooling')],['custom','settings',t('自定义','Custom'),t('编辑温控曲线','Edit fan curves')]].map(([key,ic,label,detail])=>`<button class="mode-card ${active===key?'active':''}" data-fan-preset="${key}" aria-pressed="${active===key}">${icon(ic)}<span><strong>${label}</strong><small>${detail}</small></span></button>`).join('')}</div>`}
function updateFanPreset(){const active=fanPresetKey();document.querySelectorAll('[data-fan-preset]').forEach(button=>{button.classList.toggle('active',button.dataset.fanPreset===active);button.setAttribute('aria-pressed',String(button.dataset.fanPreset===active))})}
function savedScenes(){return Array.isArray(state.prefs.scenes)?state.prefs.scenes.filter(scene=>scene&&typeof scene.name==='string'&&scene.settings&&typeof scene.settings==='object').slice(0,24):[]}
function sceneSettings(){const settings={};for(const device of lights()){const setting=effective(device.id);if(validLight(setting))settings[device.id]=clone(setting)}return settings}
async function saveScene(name){name=name.trim();if(!name||name.length>40)throw new Error(t('请输入 1–40 字的场景名称','Enter a scene name with 1–40 characters'));const settings=sceneSettings();if(!Object.keys(settings).length)throw new Error(t('请先配置至少一个灯光设备','Configure at least one lighting device first'));const scenes=savedScenes().filter(scene=>scene.name!==name);if(scenes.length>=24)throw new Error(t('最多保存 24 个场景，请先删除旧场景','Limit of 24 scenes reached; delete a scene first'));scenes.push({id:crypto.randomUUID(),name,settings});await persist({scenes})}
function loadScene(scene){const draft=clone(state.lighting);if(draft.sync){for(const id of draft.members){if(!validLight(draft.independent[id]))throw new Error(t('独立配置缺失，无法载入场景','Independent configuration missing; cannot load scene'));draft.devices[id]=clone(draft.independent[id])}}draft.sync=false;draft.members=[];draft.independent={};let count=0;for(const device of lights()){const setting=normalizeLight(scene.settings[device.id]);if(!setting)continue;if(!supportsEffect(device,setting.effect))throw new Error(t('场景包含当前设备不支持的灯效','A scene effect is unsupported by the current device'));draft.devices[device.id]=setting;count++}if(!count)throw new Error(t('场景中的设备当前未连接','No devices from this scene are connected'));state.lighting=draft;state.lightingDirty=true}
function sceneDialog(){document.querySelector('.save-menu')?.removeAttribute('open');showModal(`<div class="modal-body"><h2>${t('保存灯光场景','Save lighting scene')}</h2><p>${t('保存当前灯光预览，不会应用设备。重名会替换原场景。','Save the current lighting preview without applying it. An existing name replaces that scene.')}</p><label class="form-field">${t('场景名称','Scene name')}<input id="scene-name" type="text" maxlength="40" autocomplete="off"></label><p class="inline-error" id="scene-error" role="alert"></p></div><div class="modal-footer"><button data-close>${t('取消','Cancel')}</button><button class="primary" id="confirm-scene">${t('保存场景','Save scene')}</button></div>`);document.getElementById('scene-name').focus();document.getElementById('confirm-scene').onclick=async()=>{const button=document.getElementById('confirm-scene');button.disabled=true;try{await saveScene(document.getElementById('scene-name').value);modal.close();toast(t('场景已保存，未应用设备','Scene saved; devices unchanged'))}catch(error){document.getElementById('scene-error').textContent=error.message}finally{button.disabled=false}}}
function scenesDialog(){const scenes=savedScenes();document.querySelector('.save-menu')?.removeAttribute('open');showModal(`<div class="modal-body"><h2>${t('我的场景','My scenes')}</h2><p>${t('载入场景后可继续编辑，保存并应用后才会更改设备。','Load a scene to preview and edit it. Devices change only after Save & apply.')}</p>${scenes.map((scene,i)=>`<div class="settings-row"><h3>${esc(scene.name)}</h3><div class="row"><button class="small" data-scene-load="${i}">${t('载入','Load')}</button><button class="small ghost" data-scene-delete="${i}">${t('删除','Delete')}</button></div></div>`).join('')||empty(t('还没有保存的场景','No saved scenes yet'))}<p id="scene-error" class="inline-error" role="alert"></p></div><div class="modal-footer"><button data-close>${t('关闭','Close')}</button></div>`);modal.querySelectorAll('[data-scene-load]').forEach(button=>button.onclick=()=>{try{loadScene(scenes[Number(button.dataset.sceneLoad)]);modal.close();render()}catch(error){document.getElementById('scene-error').textContent=error.message}});modal.querySelectorAll('[data-scene-delete]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await persist({scenes:scenes.filter((_,i)=>i!==Number(button.dataset.sceneDelete))});scenesDialog()}catch(error){document.getElementById('scene-error').textContent=error.message;button.disabled=false}})}
function bindSceneMenu(){document.getElementById('save-scene')?.addEventListener('click',sceneDialog);document.getElementById('open-scenes')?.addEventListener('click',scenesDialog);document.querySelector('.save-menu')?.addEventListener('keydown',event=>{if(event.key==='Escape'){event.currentTarget.open=false;event.currentTarget.querySelector('summary').focus()}})}
function selectedFan(){return fans().find(d=>d.id===state.fanSelected)||fans()[0]}
function ensureFan(){const d=selectedFan();if(d&&state.fanSelected!==d.id){state.fanSelected=d.id;state.fanDraft=clone(d.metadata?.profile||null);state.fanDirty=false}return d}
function cooling(){const d=ensureFan();return head(t('散热','Cooling'),t('风扇控制与温度监测','Fan control and temperature monitoring'),!!d)+(state.connected?`${d?fanPresets():''}<div class="cool-layout">${d?fanEditor(d):`<section class="section">${empty(t('暂无可调风扇，仍可查看温度与转速。','No adjustable fans. Temperature and speed readings remain available.'))}</section>`}<section class="section cooling-readouts"><div class="section-head"><h2>${t('当前状态','Current readings')}</h2><span class="badge">${t('水泵只读','Pump read-only')}</span></div>${telemetryReadouts()}</section></div><div class="grid2 chart-section cooling-history"><section class="section"><h2>${t('温度变化','Temperature history')}</h2>${historyPanels('temperature',1,true)}</section><section class="section"><h2>${t('转速历史','Fan speed history')}</h2>${historyPanels('fanRpm',2,true)}</section></div>`:setupCard())}
function fanEditor(d){const profile=state.fanDraft;if(!profile)return `<section class="section">${empty(t('服务未提供可编辑 FanProfile。请刷新设备。','The service did not provide an editable FanProfile. Rediscover devices.'))}</section>`;const points=profile[state.fanTarget+'Curve']||[];const minimum=state.fanTarget==='radiator'?40:25;return `<section class="section"><div class="section-head"><div><h2>${esc(deviceLabel(d))}</h2><p>${t('升温时加速，降温后平缓回落','Speed up as temperature rises; ease back as it falls')}</p></div><select id="fan-device" aria-label="${t('散热控制器','Cooling controller')}">${fans().map((fan,i)=>`<option value="${i}" ${fan.id===d.id?'selected':''}>${esc(deviceLabel(fan))}</option>`).join('')}</select></div><div class="row spaced"><label class="form-field">${t('控制模式','Control mode')}<select id="fan-mode"><option value="curve" ${profile.mode==='curve'?'selected':''}>${t('温控曲线','Temperature curve')}</option><option value="manual" ${profile.mode==='manual'?'selected':''}>${t('手动百分比（保留高温保护）','Manual duty (thermal protection retained)')}</option></select></label><div class="fan-select"><button data-target="radiator" class="small ${state.fanTarget==='radiator'?'active':''}">${t('冷排','Radiator')}</button><button data-target="case" class="small ${state.fanTarget==='case'?'active':''}">${t('机箱','Case')}</button></div></div>${profile.mode==='manual'?`<div class="manual-fields">${[['radiator',40,t('冷排','Radiator')],['case',25,t('机箱','Case')]].map(([key,min,label])=>`<label class="form-field">${label} %<input type="number" data-manual="${key}" min="${min}" max="100" value="${profile[key+'Percent']}"></label>`).join('')}</div>`:''}${curveChart(points,minimum)}<details class="curve-numbers"><summary>${t('编辑数值','Edit values')}</summary><table class="table-view"><thead><tr><th>${t('温度 °C','Temperature °C')}</th><th>${t('风扇百分比','Fan duty %')}</th></tr></thead><tbody>${points.map((point,i)=>`<tr><td><input type="number" data-point-temperature="${i}" value="${point.temperature}" min="0" max="80" ${i===points.length-1?'disabled':''} aria-label="${t('节点温度','Point temperature')} ${i+1}"></td><td><input type="number" data-point-duty="${i}" value="${point.duty}" min="${minimum}" max="100" ${i===points.length-1?'disabled':''} aria-label="${t('节点百分比','Point duty')} ${i+1}"> %</td></tr>`).join('')}</tbody></table></details><div class="note">${icon('shield')}${t('80°C 满速保护；冷排最低 40%，机箱最低 25%。百分比不是固定 RPM。水泵不写入。','Full duty at 80°C; minimum 40% radiator and 25% case. Duty is not a fixed RPM. Pump controls are never written.')}</div><div class="restore-row"><small>${esc(statusLabel(d.metadata?.session?.status))} ${d.metadata?.session?.active&&d.metadata.session.expiresUtc===null?t('持续控制，直到恢复原始控制','Continuous control until restored'):d.metadata?.session?.active&&d.metadata.session.expiresUtc?esc(t('到期时间 ','Expires ')+formatTime(d.metadata.session.expiresUtc)):''}</small>${has(d,Capabilities.Release)?`<button id="restore-fans">${icon('undo')}${t('恢复原始控制','Restore original control')}</button>`:''}</div><p class="graph-hint">${t('正常释放由服务执行并验证。强制结束工作进程或系统崩溃不能保证恢复。','The service restores and verifies normal release. Worker or OS crashes cannot guarantee restoration.')}</p></section>`}
function metadataFields(object){if(!object||typeof object!=='object')return '';return Object.entries(object).filter(([key])=>!['schemaVersion','readOnly','diagnostics'].includes(key)).map(([key,value])=>`<div><dt>${esc(key)}</dt><dd>${esc(typeof value==='object'?JSON.stringify(value):value??'—')}</dd></div>`).join('')}
function computer(){const info=devices().filter(d=>has(d,Capabilities.SystemInfo));return head(t('我的电脑','My computer'),t('服务读取的硬件配置与系统策略','Hardware information and system policies from the service'))+(!state.connected?setupCard():`<div class="grid2">${info.map(d=>`<section class="section"><div class="section-head"><h2>${esc(deviceLabel(d))}</h2><span class="badge">${t('只读','Read-only')}</span></div>${Array.isArray(d.metadata?.components)?d.metadata.components.map(component=>`<dl class="spec-list"><div><dt>${esc(component.kind)}</dt><dd>${esc(component.name)}<small>${esc(component.manufacturer||'')} ${finite(component.capacityBytes)?esc((component.capacityBytes/1073741824).toFixed(1)+' GiB'):''}</small></dd></div></dl>`).join(''):`<dl class="spec-list">${metadataFields(d.metadata)}</dl>`}${(d.metadata?.diagnostics||[]).map(x=>`<p class="graph-hint">${esc(x)}</p>`).join('')}</section>`).join('')||`<section class="section">${empty(t('未读取系统信息。请启用系统信息插件。','System information unavailable. Enable a system information plugin.'))}</section>`}<section class="section"><h2>${t('已连接设备','Connected devices')}</h2>${deviceRows(devices().filter(d=>!has(d,Capabilities.SystemInfo)))}</section></div>${policyPanels()}`)}
function policyPanels(){return devices().filter(d=>has(d,Capabilities.PowerWindowsScheme)||has(d,Capabilities.ProcessPolicy)).map((d,i)=>{const p=d.metadata||{},schemes=p.power?.schemes||[],processes=p.process?.processes||[];return `<section class="section chart-section" data-policy-index="${i}"><div class="section-head"><h2>${esc(deviceLabel(d))}</h2>${has(d,Capabilities.Release)?`<button class="small policy-restore">${icon('undo')}${t('恢复原始策略','Restore original policies')}</button>`:''}</div>${has(d,Capabilities.PowerWindowsScheme)?`<div class="policy-block"><h3>${t('电源计划','Power scheme')}</h3><p class="graph-hint">${t('切换 Windows 提供的电源计划；不改写 GPU 参数。','Switch a Windows power scheme. GPU parameters remain unchanged.')}</p>${schemes.length?`<div class="policy-form"><select class="scheme-select" aria-label="${t('电源计划','Power scheme')}">${schemes.map((s,n)=>`<option value="${n}" ${s.isActive||s.active||s.id===p.power.activeSchemeId?'selected':''}>${esc(s.name)}</option>`).join('')}</select><button class="scheme-apply">${t('应用计划','Apply scheme')}</button></div>`:empty(t('服务未提供电源计划','No power schemes available'))}</div>`:''}${has(d,Capabilities.ProcessPolicy)?`<div class="policy-block"><h3>${t('进程策略','Process policy')}</h3><p class="graph-hint">${t('仅作用于所选进程的当前实例。需自动应用时，可创建进程自动化规则。','Apply to the selected running instance. Create a process automation rule for automatic control.')}</p>${processes.length?`<div class="policy-form"><select class="process-select" aria-label="${t('进程','Process')}">${processes.map((p,n)=>`<option value="${n}">${esc(p.name)} · PID ${esc(p.pid)} · ${esc(p.priority)}</option>`).join('')}</select><select class="priority-select" aria-label="${t('优先级','Priority')}">${(p.process.allowedPriorities||p.process.priorities||Priorities).map(v=>`<option ${v==='Normal'?'selected':''}>${esc(v)}</option>`).join('')}</select>${p.process.affinityWriteSupported?`<input class="affinity" placeholder="${t('可选 CPU 掩码','Optional affinity mask')}" aria-label="${t('CPU 亲和性掩码','CPU affinity mask')}" maxlength="20">`:''}<button class="process-apply">${t('应用策略','Apply policy')}</button></div>`:empty(t('无可配置的进程','No configurable processes'))}<p class="graph-hint">${t('进程启动时间用于验证身份，PID 被重用时不会误改新进程。','Start time verifies identity so a reused PID cannot target a new process.')}</p></div>`:''}</section>`}).join('')}
function settings(){return head(t('设置','Settings'),t('应用偏好与设备管理','Preferences and device management'))+`<section class="section"><div class="permission-box">${icon('shield')}<div><h2>${state.connected?t('后台服务已就绪','Background service ready'):t('后台服务尚未连接','Background service unavailable')}</h2><p>${t('设备操作交给本地受限服务。安装、修复或卸载可能要求管理员授权。','A restricted local service handles devices. Setup, repair and removal may need administrator approval.')}</p></div></div><div class="settings-row"><div><h3>${t('界面语言','Interface language')}</h3><p>${t('偏好通过本地服务原子保存','Preferences are saved atomically through the local service')}</p></div><select id="language" aria-label="Language"><option value="zh-CN" ${state.language==='zh-CN'?'selected':''}>简体中文</option><option value="en" ${state.language==='en'?'selected':''}>English</option></select></div><div class="settings-row"><div><h3>${t('外观','Appearance')}</h3><p>${t('自动模式跟随 Windows 的深浅主题','Automatic mode follows the Windows color theme')}</p></div><select id="theme" aria-label="${t('外观主题','Appearance theme')}">${[[Themes.Auto,t('跟随系统','Automatic')],[Themes.Light,t('浅色','Light')],[Themes.Dark,t('深色','Dark')]].map(([value,label])=>`<option value="${value}" ${state.theme===value?'selected':''}>${label}</option>`).join('')}</select></div><div class="settings-row"><div><h3>${t('启动服务时恢复灯光配置','Restore lighting when the service starts')}</h3><p>${t('仅恢复已成功应用的灯光。默认关闭；不会重放未确认完成的操作。','Restore successfully applied lighting only. Off by default; unconfirmed operations are not replayed.')}</p></div><button id="restore-lighting-startup" class="switch ${state.prefs.restoreLightingOnStartup===true?'on':''}" role="switch" aria-checked="${state.prefs.restoreLightingOnStartup===true}" aria-label="${t('启动服务时恢复灯光配置','Restore lighting when the service starts')}" ${!preferencesLoaded?'disabled':''}></button></div><div class="settings-row"><div><h3>${t('启动服务时恢复散热配置','Restore cooling when the service starts')}</h3><p>${t('仅恢复已保存的风扇配置。默认关闭，水泵保持只读。','Restore saved fan profiles only. Off by default; pump controls remain read-only.')}</p></div><button id="restore-cooling-startup" class="switch ${state.prefs.restoreCoolingOnStartup===true?'on':''}" role="switch" aria-checked="${state.prefs.restoreCoolingOnStartup===true}" aria-label="${t('启动服务时恢复散热配置','Restore cooling when the service starts')}" ${!preferencesLoaded?'disabled':''}></button></div><div class="settings-row"><div><h3>${t('硬件服务','Hardware service')}</h3><p>${esc(state.error||t('刷新设备发现，或打开首次配置与修复。','Rediscover devices, or open setup and repair.'))}</p></div><div class="row"><button id="refresh">${t('重新发现','Rediscover')}</button><button id="setup-service">${t('安装与修复','Setup & repair')}</button></div></div><div class="settings-row"><div><h3>${t('设备与扩展','Devices and extensions')}</h3><p>${t('插件由安装程序管理；界面只查看已配置插件。','Setup manages plugins. This interface shows configured plugins.')}</p></div><button id="plugins-open">${t('查看插件','View plugins')}</button></div><div class="settings-row"><div><h3>${t('关闭窗口时','When the window closes')}</h3><p>${t('最小化到托盘，后台控制继续。退出界面不会停止服务。','Hide to tray and keep background control. Exiting the UI does not stop the service.')}</p></div><button id="exit-app">${t('退出界面','Exit UI')}</button></div><div class="settings-row"><div><h3>${t('恢复并退出','Restore and exit')}</h3><p>${t('恢复支持释放的控制器和同步前灯光。任何设备失败时保留窗口与错误详情。','Restore releasable controllers and pre-sync lighting. Any failure keeps the window open with details.')}</p></div><button id="release-exit" ${!state.connected?'disabled':''}>${t('恢复并退出','Restore & exit')}</button></div></section>${(state.snapshot.diagnostics||[]).length?`<section class="section chart-section"><h2>${t('服务诊断','Service diagnostics')}</h2>${state.snapshot.diagnostics.map(d=>`<p class="graph-hint">${esc(d)}</p>`).join('')}</section>`:''}`}
function render(){applyTheme();const names={overview:t('总览','Overview'),lighting:t('灯光','Lighting'),cooling:t('散热','Cooling'),automation:t('自动化','Automation'),computer:t('我的电脑','My computer'),settings:t('设置','Settings')};document.documentElement.lang=state.language;document.getElementById('brand-name').textContent=t('光序','LightOrder');document.getElementById('brand-subtitle').textContent=t('灯光与散热','Lighting & cooling');document.querySelectorAll('[data-page]').forEach(b=>{b.classList.toggle('active',b.dataset.page===state.page);b.querySelector('span').textContent=names[b.dataset.page]});main.innerHTML=(state.errors.length?`<div class="failure-list" role="alert"><strong>${t('操作未全部完成','Operation incomplete')}</strong>${state.errors.map(e=>`<p>${esc(e)}</p>`).join('')}</div>`:'')+({overview,lighting,cooling,automation,computer,settings}[state.page])();main.classList.toggle('busy',state.busy);hydrateIcons();bindPage()}
function navigate(page){if(state.busy)return;if((state.lightingDirty||state.fanDirty)&&page!==state.page){showModal(`<div class="modal-body"><h2>${t('还有未保存的修改','Unsaved changes')}</h2><p>${t('离开会丢弃当前预览。已应用的硬件状态不变。','Leaving discards the current draft. Applied hardware settings stay unchanged.')}</p></div><div class="modal-footer"><button data-close>${t('继续编辑','Keep editing')}</button><button id="leave-page">${t('丢弃并离开','Discard and leave')}</button></div>`);document.getElementById('leave-page').onclick=()=>{discard();state.page=page;modal.close();render();if(page==='automation')loadAutomation()};return}state.page=page;render();if(page==='automation')loadAutomation();main.focus();window.scrollTo(0,0)}
function discard(){if(state.lightingDirty){state.lighting=clone(state.savedLighting);state.lightingDirty=false}if(state.fanDirty){state.fanDraft=clone(selectedFan()?.metadata?.profile||null);state.fanDirty=false}}
function bindPage(){bindSceneMenu();bindAutomation();document.getElementById('restore-lighting-startup')?.addEventListener('click',()=>action(()=>persist({restoreLightingOnStartup:state.prefs.restoreLightingOnStartup!==true})));document.getElementById('restore-cooling-startup')?.addEventListener('click',()=>action(()=>persist({restoreCoolingOnStartup:state.prefs.restoreCoolingOnStartup!==true})));document.querySelectorAll('[data-go-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.goPage));document.getElementById('theme')?.addEventListener('change',event=>{const theme=event.target.value;action(async()=>{if(!Object.values(Themes).includes(theme))throw new Error(t('主题无效','Invalid theme'));await persist({theme});state.theme=theme;applyTheme()})});document.getElementById('retry')?.addEventListener('click',()=>refresh(false));document.getElementById('refresh')?.addEventListener('click',()=>refresh(true));document.getElementById('setup-service')?.addEventListener('click',()=>action(async()=>{await rpc('setup.open');toast(t('安装程序已启动；完成后请重试连接。','Setup launched. Retry connection after setup.'))}));document.getElementById('go-lights')?.addEventListener('click',()=>navigate('lighting'));document.getElementById('apply')?.addEventListener('click',()=>state.page==='lighting'?applyLighting():applyFan());document.getElementById('discard')?.addEventListener('click',()=>{discard();render()});document.querySelectorAll('[data-device-index]').forEach(b=>b.onclick=()=>{state.selected=lights()[Number(b.dataset.deviceIndex)].id;render()});document.getElementById('sync-toggle')?.addEventListener('click',()=>state.lighting.sync?disableSync():syncDialog());document.getElementById('members')?.addEventListener('click',syncDialog);bindLightEditor();bindFanEditor();bindHistoryCharts();bindPolicies();document.getElementById('plugins-open')?.addEventListener('click',()=>action(async()=>{const result=await rpc('app.plugins');const list=Array.isArray(result)?result:result.plugins||[];showModal(`<div class="modal-body"><h2>${t('已配置插件','Configured plugins')}</h2>${list.map(p=>`<div class="device-line"><div><h3>${esc(p.name)}</h3><small>${esc(p.version)} · ${p.enabled?t('已启用','Enabled'):t('未启用','Disabled')}</small></div></div>`).join('')||empty(t('暂无配置插件','No configured plugins'))}</div><div class="modal-footer"><button data-close>${t('关闭','Close')}</button></div>`)}));document.getElementById('language')?.addEventListener('change',event=>action(async()=>{state.language=event.target.value;await persist({language:state.language});render()}));document.getElementById('exit-app')?.addEventListener('click',()=>rpc('window.exit').catch(()=>{}));document.getElementById('release-exit')?.addEventListener('click',releaseAndExit)}
async function action(fn){if(state.busy)return;state.busy=true;state.errors=[];render();try{await fn()}catch(e){state.errors=[e.message]}finally{state.busy=false;render()}}
async function persist(extra={}){if(!preferencesLoaded)throw new Error(t('尚未成功读取配置，请重新连接后再保存。','Preferences have not been loaded. Reconnect before saving.'));const doc={...state.prefs,schemaVersion:1,language:state.language,...extra};await rpc('profiles.write',doc);state.prefs=doc}
async function execute(deviceId,capability,parameters){const result=await rpc('app.execute',{deviceId,capability,parameters});const status=String(result?.status).toLowerCase();const lighting=[Capabilities.LightingStatic,Capabilities.LightingOff,Capabilities.LightingEffect].includes(capability);if(!result||!([ApplyStatus.Applied,ApplyStatus.Unchanged,ApplyStatus.Restored,ApplyStatus.Released,ApplyStatus.Verified].includes(status)||(lighting&&status===ApplyStatus.Accepted)))throw new Error(result?.detail||t('服务未确认操作完成','The service did not confirm completion'));return result}
async function applyLighting(){await action(async()=>{const target=clone(state.lighting);const previous=state.savedLighting;const ids=new Set([...Object.keys(target.devices),...target.members,...(previous?.members||[])]);const changed=[...ids].filter(id=>JSON.stringify(effective(id,target))!==JSON.stringify(effective(id,previous)));if(!changed.length){state.lightingDirty=false;return}for(const id of changed){const setting=effective(id,target);if(!validLight(setting))throw new Error(t('配置不完整，无法应用','Incomplete lighting setting'));if(!supportsEffect(deviceById(id),setting.effect))throw new Error(t('目标设备未声明此灯效能力','A target device does not advertise this effect'))}await persist({lighting:previous,pendingLighting:target});const failures=[];const applied={...(state.prefs.appliedLighting||{})};const phaseUtc=new Date().toISOString();for(const id of changed){const setting=effective(id,target);try{const command=lightCommand(id,setting,phaseUtc);await execute(command.deviceId,command.capability,command.parameters);applied[id]=clone(setting)}catch(e){failures.push(`${deviceById(id)?.name||id}: ${e.message}`)}}if(failures.length){await persist({appliedLighting:applied}).catch(e=>failures.push(e.message));state.errors=failures;return}await persist({lighting:target,pendingLighting:null,appliedLighting:applied});state.savedLighting=clone(target);state.lightingDirty=false;toast(t('已保存并应用；不代表物理灯光读回','Saved and applied; not physical lighting readback'));await refresh(false,true)})}
function validateProfile(p){if(!p||!['curve','manual'].includes(p.mode))throw new Error(t('控制模式无效','Invalid mode'));for(const [key,min] of [['radiator',40],['case',25]]){if(!finite(p[key+'Percent'])||p[key+'Percent']<min||p[key+'Percent']>100)throw new Error(t('手动百分比超出范围','Manual duty out of range'));const points=p[key+'Curve'];if(!Array.isArray(points)||points.length<2||points.length>12)throw new Error(t('曲线需要 2–12 个节点','A curve requires 2–12 points'));points.forEach((point,i)=>{if(!finite(point.temperature)||!finite(point.duty)||point.temperature<0||point.temperature>80||point.duty<min||point.duty>100||(i&&(point.temperature<=points[i-1].temperature||point.duty<points[i-1].duty)))throw new Error(t('温度必须递增，风扇百分比不能随温度下降','Temperatures must increase and duty must not decrease'))});if(points.at(-1).temperature!==80||points.at(-1).duty!==100)throw new Error(t('末节点必须为 80°C / 100%','Last point must be 80°C / 100%'))}}
async function applyFan(){await action(async()=>{validateProfile(state.fanDraft);const d=selectedFan();await execute(d.id,Capabilities.FanProfile,state.fanDraft);try{await persist({fanProfiles:{...(state.prefs.fanProfiles||{}),[d.id]:clone(state.fanDraft)}})}catch(error){throw new Error(t('风扇配置已应用，但保存失败；重启时可能无法恢复：','Fan profile applied, but saving failed; startup restore may be unavailable: ')+error.message)};state.fanDirty=false;toast(t('风扇配置已应用','Fan profile applied'));await refresh(true,true)})}
async function restoreDevice(d){await execute(d.id,Capabilities.Release,{});toast(t('服务已完成恢复','Service completed restoration'));await refresh(true,true);if(state.fanSelected===d.id){state.fanDraft=clone(deviceById(d.id)?.metadata?.profile||null);state.fanDirty=false}}
async function releaseAndExit(){await action(async()=>{const failures=[];if(state.lighting.sync){for(const id of state.lighting.members){const setting=state.lighting.independent[id];if(!validLight(setting)){failures.push(t('缺少独立灯光快照','Missing independent lighting snapshot'));continue}try{const command=lightCommand(id,setting);await execute(command.deviceId,command.capability,command.parameters)}catch(e){failures.push(`${deviceById(id)?.name||id}: ${e.message}`)}}}for(const d of devices().filter(d=>has(d,Capabilities.Release)&&(has(d,Capabilities.FanProfile)||has(d,Capabilities.PowerWindowsScheme)||has(d,Capabilities.ProcessPolicy)))){try{await execute(d.id,Capabilities.Release,{})}catch(e){failures.push(`${d.name}: ${e.message}`)}}if(failures.length){state.errors=failures;return}if(state.lighting.sync){for(const id of state.lighting.members)state.lighting.devices[id]=clone(state.lighting.independent[id]);state.lighting.sync=false;state.lighting.members=[];state.lighting.independent={};await persist({lighting:state.lighting,pendingLighting:null})}await rpc('window.exit')})}
function bindPolicies(){const policies=devices().filter(d=>has(d,Capabilities.PowerWindowsScheme)||has(d,Capabilities.ProcessPolicy));document.querySelectorAll('[data-policy-index]').forEach(root=>{const d=policies[Number(root.dataset.policyIndex)];root.querySelector('.policy-restore')?.addEventListener('click',()=>action(()=>restoreDevice(d)));root.querySelector('.scheme-apply')?.addEventListener('click',()=>{const scheme=d.metadata.power.schemes[Number(root.querySelector('.scheme-select').value)];action(async()=>{await execute(d.id,Capabilities.PowerWindowsScheme,{schemeId:scheme.id});await refresh(true,true);toast(t('电源计划已应用','Power scheme applied'))})});root.querySelector('.process-apply')?.addEventListener('click',()=>{const process=d.metadata.process.processes[Number(root.querySelector('.process-select').value)];const priority=root.querySelector('.priority-select').value,mask=root.querySelector('.affinity')?.value.trim();action(async()=>{if(!Number.isInteger(process?.pid)||!Number.isFinite(Date.parse(process?.startTimeUtc)))throw new Error(t('进程身份已失效，请刷新','Process identity is unavailable. Refresh processes.'));if(mask&&!/^(?:0x)?[0-9a-f]+$/i.test(mask))throw new Error(t('请输入十六进制亲和性掩码','Enter a hexadecimal affinity mask'));const parameters={pid:process.pid,startTimeUtc:process.startTimeUtc,priority};if(mask)parameters.affinityMask=mask;await execute(d.id,Capabilities.ProcessPolicy,parameters);await refresh(true,true);toast(t('进程策略已应用','Process policy applied'))})})})}
function ingest(snapshot){state.snapshot=snapshot;const now=Date.now();for(const sample of snapshot.telemetry||[]){const time=Date.parse(sample.timestamp);if(!Number.isFinite(time))continue;const key=JSON.stringify([sample.deviceId,sample.name,sample.type,sample.unit]);const series=state.history.get(key)||{name:sample.name,type:sample.type,unit:sample.unit,deviceId:sample.deviceId,points:[]};if(series.points.at(-1)?.time!==time)series.points.push({time,value:finite(sample.value)?sample.value:null});series.points=series.points.filter(p=>p.time>=now-600000).slice(-300);state.history.set(key,series)}for(const [key,series] of state.history){series.points=series.points.filter(p=>p.time>=now-600000);if(!series.points.length)state.history.delete(key)}if(state.history.size>128){for(const key of [...state.history.keys()].slice(0,state.history.size-128))state.history.delete(key)}for(const d of lights()){if(!state.lighting.devices[d.id]){const current=normalizeLight(d.metadata?.current);if(current)state.lighting.devices[d.id]=current}}if(!state.lightingDirty)state.savedLighting=clone(state.lighting);if(!state.fanDirty&&state.fanSelected)state.fanDraft=clone(selectedFan()?.metadata?.profile||null)}
async function refresh(discover=false,silent=false){if(polling)return;polling=true;try{const snapshot=await rpc(discover?'app.refresh':'app.snapshot');if(snapshot.demo||String(snapshot.version).split('.')[0]!=='1')throw new Error(t('服务版本不兼容','Incompatible service version'));const reconnect=!state.connected;state.connected=true;state.loading=false;state.error='';ingest(snapshot);if(!preferencesLoaded)await loadPreferences();if(reconnect||!silent)render();if(reconnect&&state.page==='automation')loadAutomation()}catch(e){state.connected=false;state.loading=false;state.error=e.message;render()}finally{polling=false}}
async function loadPreferences(){if(preferencesLoaded)return;if(state.connected){try{const prefs=await rpc('profiles.read');if(prefs.schemaVersion===1){state.prefs=prefs;preferencesLoaded=true;state.language=prefs.language==='en'?'en':'zh-CN';state.theme=Object.values(Themes).includes(prefs.theme)?prefs.theme:Themes.Auto;applyTheme();if(prefs.lighting&&typeof prefs.lighting.devices==='object'){const saved=prefs.lighting;const clean={devices:{},sync:!!saved.sync,members:Array.isArray(saved.members)?saved.members.filter(x=>typeof x==='string'):[],independent:{},group:normalizeLight(saved.group)||state.lighting.group};for(const [id,value] of Object.entries(saved.devices))if(validLight(value))clean.devices[id]=normalizeLight(value);for(const [id,value] of Object.entries(saved.independent||{}))if(validLight(value))clean.independent[id]=normalizeLight(value);if(clean.sync&&clean.members.some(id=>!clean.independent[id])){clean.sync=false;state.errors.push(t('同步快照不完整，未恢复同步状态。','Sync snapshot is incomplete; sync state was not restored.'))}state.lighting=clean}ingest(state.snapshot);state.savedLighting=clone(state.lighting);if(prefs.pendingLighting)state.errors.push(t('上次灯光应用未完整确认。已保留独立快照；请核对设备状态后重新配置。','The previous lighting operation was not fully confirmed. Independent snapshots are preserved; check devices before reconfiguring.'))}}catch(e){state.errors.push(e.message)}render()}}
async function startup(){render();await refresh(false);setInterval(async()=>{if(state.busy||modal.open)return;await refresh(false,true);if(!state.connected)return;if(['overview','cooling'].includes(state.page)&&!state.fanDirty&&!main.querySelector('details[open]')&&document.activeElement?.tagName!=='INPUT'&&document.activeElement?.tagName!=='SELECT')render()},3000)}
window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.theme===Themes.Auto)applyTheme()});
document.querySelectorAll('[data-page]').forEach(button=>button.onclick=()=>navigate(button.dataset.page));document.querySelector('.brand').onclick=event=>{event.preventDefault();navigate('overview')};startup();
